import React from 'react';
import { FiFileText, FiDownload, FiExternalLink } from 'react-icons/fi';

const PDFViewer = ({ pdfUrl, fileName, title = 'PDF Document' }) => {
  const cleanName = fileName || (pdfUrl ? pdfUrl.split('/').pop().split('?')[0] : 'document.pdf');

  const handlePDFDownload = (e) => {
    if (e) e.stopPropagation();
    if (!pdfUrl) return;

    if (pdfUrl.includes('cloudinary.com')) {
      // Add fl_attachment flag for forced download so browser downloads PDF instead of streaming raw text (%PDF-1.4)
      const downloadUrl = pdfUrl.includes('/upload/fl_attachment/')
        ? pdfUrl
        : pdfUrl.replace('/upload/', '/upload/fl_attachment/');
      window.open(downloadUrl, '_blank');
    } else {
      // For non-Cloudinary URLs / local uploads
      const link = document.createElement('a');
      link.href = pdfUrl;
      link.download = cleanName;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  return (
    <div
      className="bg-white p-md rounded-card border border-borderLight flex flex-col justify-between hover:shadow-md transition-shadow group relative cursor-pointer"
      onClick={handlePDFDownload}
    >
      <div className="flex items-start gap-sm mb-md">
        <div className="p-md bg-red-50 text-red-600 rounded-lg shrink-0 group-hover:scale-105 transition-transform">
          <FiFileText size={32} />
        </div>
        <div className="overflow-hidden flex-1">
          <span className="text-[10px] font-bold uppercase tracking-wider text-red-600 bg-red-100/60 px-1.5 py-0.5 rounded inline-block mb-1">
            PDF Document
          </span>
          <h4 className="text-sm font-bold text-textPrimary truncate" title={title || cleanName}>
            {title || cleanName}
          </h4>
          <p className="text-xs text-textSecondary truncate mt-0.5" title={cleanName}>
            {cleanName}
          </p>
        </div>
      </div>

      <div className="flex items-center gap-xs pt-xs border-t border-borderLight">
        <button
          onClick={handlePDFDownload}
          className="btn-primary flex-1 py-xs px-sm text-xs flex items-center justify-center gap-xs font-semibold shadow-xs"
        >
          <FiDownload size={14} />
          <span>Download PDF</span>
        </button>

        <button
          onClick={(e) => {
            e.stopPropagation();
            if (pdfUrl.includes('cloudinary.com')) {
              const downloadUrl = pdfUrl.includes('/upload/fl_attachment/')
                ? pdfUrl
                : pdfUrl.replace('/upload/', '/upload/fl_attachment/');
              window.open(downloadUrl, '_blank');
            } else {
              window.open(pdfUrl, '_blank');
            }
          }}
          className="btn-secondary py-xs px-sm text-xs flex items-center justify-center text-textSecondary hover:text-textPrimary hover:bg-bgLight"
          title="Open or Download"
        >
          <FiExternalLink size={14} />
        </button>
      </div>
    </div>
  );
};

export default PDFViewer;
